  "contradictory_card_ids": ["C18"],
  "prediction_basis_card_ids": ["C04", "C10", "C14", "C07", "C11", "C08", "C02"],
  "claims": [
    {
      "claim": "The query is a rigid N-methyl morphinan opioid (hydromorphone-like) with a phenolic C3 and basic amine; the closest measured human analogue, codeine, has absolute oral bioavailability of 80.5% in healthy subjects (C04) and relative oral bioavailability of 50.2% vs intramuscular dosing in non-smokers (C17, C30), both well above the 20% threshold.",
      "card_ids": ["C04", "C17", "C30"]
    },
    {
      "claim": "Other opioid contexts also report F above 20%: pethidine 0.80±0.15 in cirrhosis (C10, C14; increased 81% in cirrhosis, C16; increased oral bioavailability in cirrhosis, C20, C24), pentazocine 0.68–0.70 in cirrhosis (C07, C11; increased, C19, C20, C24), meptazinol 27.9% in cirrhosis (C08, C22, C29), and naloxegol simulated F 0.90 (C02; oral bioavailability described, C21, C28).",
      "card_ids": ["C10", "C14", "C16", "C20", "C24", "C07", "C11", "C19", "C08", "C22", "C29", "C02", "C21", "C28"]
    },
    {
      "claim": "The only visible low-F record is indacaterol in CD-1 mice (1%, C18), a non-opioid with low applicability to the query; it does not provide affirmative threshold-relevant evidence for hydromorphone F<20%.",
      "card_ids": ["C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C17", "C30"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C16", "C19", "C20", "C21", "C22", "C24", "C28", "C29"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C18"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C23", "C25", "C26", "C27"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present in the visible set.",
    "Several opioid records are cirrhosis-conditioned; cirrhosis increases F by reducing first-pass metabolism, so exact healthy-subject transfer is uncertain (e.g., meptazinol 27.9% in cirrhosis is a four-fold increase over controls, C22).",
    "Codeine relative bioavailability (C17, C30) is vs intramuscular, not intravenous, so it is not a pure absolute F value.",
    "Naloxegol F 0.90 is a PBPK simulation (C02), not a measured clinical absolute F for the query scaffold.",
    "No dose-, formulation-, or prandial-state-matched hydromorphone data are available."
  ],
  "decision_summary": "New L2 records corroborate the L1 opioid evidence (codeine 50.2% relative, pethidine/pentazocine increases in cirrhosis, naloxegol oral bioavailability, meptazinol 27.9%) and add no transferable negative for the query; the only low-F record is indacaterol in mice. Prediction remains high; confidence high; revision strengthened."
}

